export const ECOSYSTEM = [
  // ---- MCQ ----
  { id: 'eco-1', type: 'mcq', question: "The term 'Ecosystem' was first coined by:", options: ['E.P. Odum', 'A.G. Tansley', 'R. Lindeman', 'Ernst Haeckel'], correctIndex: 1, explanation: 'A.G. Tansley coined the term "ecosystem" in 1935.', difficulty: 'easy' },
  { id: 'eco-2', type: 'mcq', question: 'An ecosystem is best defined as:', options: ['A group of similar species living together', 'A functional unit where living organisms interact among themselves and their physical environment', 'A geographic area with uniform climate', 'The total biomass of producers in a region'], correctIndex: 1, explanation: 'An ecosystem is a functional unit of nature involving interaction between biotic communities and their abiotic environment.', difficulty: 'easy' },
  { id: 'eco-3', type: 'mcq', question: 'The autotrophic component of an ecosystem is represented by:', options: ['Decomposers', 'Producers', 'Primary consumers', 'Secondary consumers'], correctIndex: 1, explanation: 'Producers (green plants, some bacteria) are the autotrophic, self-nourishing component.', difficulty: 'easy' },
  { id: 'eco-4', type: 'mcq', question: 'Which of these is a heterotrophic component of an ecosystem?', options: ['Green plants', 'Cyanobacteria', 'Consumers and decomposers', 'Chemoautotrophic bacteria'], correctIndex: 2, explanation: 'Consumers and decomposers depend on organic matter made by producers, making them heterotrophic.', difficulty: 'easy' },
  { id: 'eco-5', type: 'mcq', question: 'In a pond ecosystem, the primary producers are mainly:', options: ['Fish', 'Phytoplankton and submerged/floating plants', 'Zooplankton', 'Benthic decomposers'], correctIndex: 1, explanation: 'Phytoplankton and aquatic plants are the photosynthetic producers of a pond ecosystem.', difficulty: 'easy' },
  { id: 'eco-6', type: 'mcq', question: 'The grazing food chain (GFC) begins with:', options: ['Dead organic matter', 'Green plants', 'Detritivores', 'Decomposers'], correctIndex: 1, explanation: 'The GFC starts at green plants (producers) and flows to herbivores and then carnivores.', difficulty: 'easy' },
  { id: 'eco-7', type: 'mcq', question: 'The detritus food chain (DFC) begins with:', options: ['Green plants', 'Sunlight energy', 'Dead organic matter', 'Herbivores'], correctIndex: 2, explanation: 'The DFC starts from dead organic matter, broken down by decomposers and detritivores.', difficulty: 'easy' },
  { id: 'eco-8', type: 'mcq', question: 'Each step of transfer of food energy from one organism to another is called a:', options: ['Food web', 'Trophic level', 'Ecological niche', 'Biome'], correctIndex: 1, explanation: 'A trophic level represents a step in the transfer of energy along a food chain.', difficulty: 'easy' },
  { id: 'eco-9', type: 'mcq', question: 'Herbivores occupy which trophic level?', options: ['Producer', 'Primary consumer', 'Secondary consumer', 'Tertiary consumer'], correctIndex: 1, explanation: 'Herbivores feed directly on producers, making them primary consumers.', difficulty: 'easy' },
  { id: 'eco-10', type: 'mcq', question: 'An organism that feeds on herbivores is called a:', options: ['Primary consumer', 'Secondary consumer', 'Decomposer', 'Producer'], correctIndex: 1, explanation: 'Carnivores that eat herbivores occupy the secondary consumer (second carnivore) level.', difficulty: 'easy' },
  { id: 'eco-11', type: 'mcq', question: 'The organism occupying the highest trophic level in a food chain is called the:', options: ['Primary producer', 'Top carnivore', 'Detritivore', 'Decomposer'], correctIndex: 1, explanation: 'The top carnivore sits at the highest trophic level, with no predators of its own within that chain.', difficulty: 'easy' },
  { id: 'eco-12', type: 'mcq', question: 'A network formed by the interconnection of multiple food chains is called a:', options: ['Food web', 'Ecological pyramid', 'Biogeochemical cycle', 'Trophic structure'], correctIndex: 0, explanation: 'A food web is the interlocking pattern of many interconnected food chains.', difficulty: 'easy' },
  { id: 'eco-13', type: 'mcq', question: 'In a grassland ecosystem, the pyramid of numbers is typically:', options: ['Inverted', 'Upright', 'Spindle-shaped', 'Rectangular'], correctIndex: 1, explanation: 'Grasslands show an upright pyramid — many grass plants supporting fewer herbivores and even fewer carnivores.', difficulty: 'medium' },
  { id: 'eco-14', type: 'mcq', question: 'The pyramid of numbers in a tree-based ecosystem is typically:', options: ['Upright', 'Inverted', 'Spindle-shaped', 'A straight vertical line'], correctIndex: 2, explanation: 'One tree (few producers) supports many insects, which support fewer birds — giving a spindle shape (narrow-wide-narrow).', difficulty: 'medium' },
  { id: 'eco-15', type: 'mcq', question: 'The pyramid of biomass in a sea/ocean ecosystem is usually:', options: ['Upright', 'Inverted', 'Always a perfect triangle', 'Impossible to construct'], correctIndex: 1, explanation: "Small phytoplankton biomass supports larger fish biomass over time due to rapid turnover — giving an inverted biomass pyramid.", difficulty: 'medium' },
  { id: 'eco-16', type: 'mcq', question: 'Which ecological pyramid is always upright, without exception?', options: ['Pyramid of numbers', 'Pyramid of biomass', 'Pyramid of energy', 'None — all can be inverted'], correctIndex: 2, explanation: 'Since energy transfer between trophic levels is never 100% efficient, the pyramid of energy is always upright.', difficulty: 'medium' },
  { id: 'eco-17', type: 'mcq', question: 'Gross Primary Productivity (GPP) refers to:', options: ['Biomass accumulated after respiratory loss', 'The total rate of organic matter production by photosynthesis', 'Rate of production by primary consumers', 'Rate of decomposition of dead matter'], correctIndex: 1, explanation: 'GPP is the total rate of photosynthetic production of organic matter, before any losses.', difficulty: 'easy' },
  { id: 'eco-18', type: 'mcq', question: 'Net Primary Productivity (NPP) is calculated as:', options: ['GPP + Respiration', 'GPP − Respiration', 'GPP × Respiration', 'GPP ÷ Standing crop'], correctIndex: 1, explanation: "NPP = GPP minus the plant's own respiratory losses (R).", difficulty: 'easy' },
  { id: 'eco-19', type: 'mcq', question: 'The productivity available for consumption by heterotrophs (herbivores and decomposers) is the:', options: ['Gross Primary Productivity', 'Net Primary Productivity', 'Secondary Productivity', 'Standing crop'], correctIndex: 1, explanation: 'NPP represents the biomass surplus available to be consumed by heterotrophs.', difficulty: 'medium' },
  { id: 'eco-20', type: 'mcq', question: 'The rate of formation of new organic matter by consumers is called:', options: ['Net Primary Productivity', 'Secondary Productivity', 'Gross Primary Productivity', 'Community productivity'], correctIndex: 1, explanation: 'Secondary productivity is the rate of new biomass formation by consumers.', difficulty: 'medium' },
  { id: 'eco-21', type: 'mcq', question: 'The total mass of living material present at any trophic level at a given time is called the:', options: ['Standing crop', 'Net productivity', 'Trophic index', 'Biotic potential'], correctIndex: 0, explanation: 'Standing crop refers to the biomass (or number) present at a trophic level at a point in time.', difficulty: 'easy' },
  { id: 'eco-22', type: 'mcq', question: 'The breaking down of detritus into smaller particles by detritivores like earthworms is called:', options: ['Leaching', 'Fragmentation', 'Catabolism', 'Humification'], correctIndex: 1, explanation: 'Fragmentation is the mechanical breakdown of detritus into smaller pieces by detritivores.', difficulty: 'easy' },
  { id: 'eco-23', type: 'mcq', question: 'The process by which water-soluble inorganic nutrients go into the soil horizon and get precipitated as unavailable salts is called:', options: ['Leaching', 'Mineralisation', 'Humification', 'Catabolism'], correctIndex: 0, explanation: 'Leaching is the downward loss of water-soluble nutrients deeper into the soil.', difficulty: 'medium' },
  { id: 'eco-24', type: 'mcq', question: 'The breakdown of detritus into simpler inorganic substances by microbial enzymes is called:', options: ['Fragmentation', 'Leaching', 'Catabolism', 'Humification'], correctIndex: 2, explanation: 'Catabolism refers to enzymatic degradation of detritus by bacteria and fungi.', difficulty: 'medium' },
  { id: 'eco-25', type: 'mcq', question: 'Humification, a key step of decomposition, leads to:', options: ['Formation of a dark, amorphous substance called humus', 'Complete conversion of humus to CO2 and water', 'Loss of all nutrients from soil', 'Rapid growth of decomposer populations only'], correctIndex: 0, explanation: 'Humification produces humus — a dark, colloidal substance resistant to microbial action.', difficulty: 'medium' },
  { id: 'eco-26', type: 'mcq', question: 'The final step of decomposition, releasing inorganic nutrients back into the soil, is called:', options: ['Fragmentation', 'Mineralisation', 'Leaching', 'Humification'], correctIndex: 1, explanation: 'Mineralisation releases inorganic nutrients (like CO2, water, nutrients) from humus back into the soil.', difficulty: 'medium' },
  { id: 'eco-27', type: 'mcq', question: 'Humus is characterised as being:', options: ['Rapidly decomposed and colourless', 'Resistant to further microbial action and dark-coloured', 'A pure inorganic mineral', 'Formed only in aquatic ecosystems'], correctIndex: 1, explanation: 'Humus is dark, amorphous, and highly resistant to further rapid microbial decomposition.', difficulty: 'medium' },
  { id: 'eco-28', type: 'mcq', question: 'Which factor does NOT significantly influence the rate of decomposition?', options: ['Chemical composition of detritus', 'Climatic conditions (temperature, moisture)', 'Colour of the organism producing the detritus', 'Availability of oxygen'], correctIndex: 2, explanation: 'Decomposition rate depends on detritus chemistry and climate/oxygen availability — not the colour of the source organism.', difficulty: 'medium' },
  { id: 'eco-29', type: 'mcq', question: 'Organisms like earthworms that feed on detritus are called:', options: ['Producers', 'Detritivores', 'Top carnivores', 'Autotrophs'], correctIndex: 1, explanation: 'Detritivores (e.g., earthworms) consume detritus as part of the decomposition process.', difficulty: 'easy' },
  { id: 'eco-30', type: 'mcq', question: 'The flow of energy in an ecosystem is:', options: ['Bidirectional and cyclic', 'Unidirectional, from sun to producers to consumers', 'Random and reversible', 'Constant at every trophic level'], correctIndex: 1, explanation: 'Energy flows one-way through an ecosystem — it cannot be recycled like nutrients.', difficulty: 'easy' },
  { id: 'eco-31', type: 'mcq', question: "The 'ten per cent law' of energy transfer between trophic levels was proposed by:", options: ['A.G. Tansley', 'R. Lindeman', 'Charles Elton', 'E.P. Odum'], correctIndex: 1, explanation: 'Raymond Lindeman formulated the 10% law describing energy loss between trophic levels.', difficulty: 'medium' },
  { id: 'eco-32', type: 'mcq', question: 'According to the ten per cent law, when energy passes from one trophic level to the next:', options: ['All the energy is transferred', 'Only about 10% is transferred, the rest is lost mostly as heat', '90% is transferred, 10% is lost', 'Energy transfer is exactly equal at every level'], correctIndex: 1, explanation: 'Roughly 10% of energy is passed on; the remaining ~90% is lost, mainly as respiratory heat.', difficulty: 'easy' },
  { id: 'eco-33', type: 'mcq', question: 'Of the incident solar radiation, the fraction that is Photosynthetically Active Radiation (PAR) is approximately:', options: ['2–10%', '50%', '90%', '100%'], correctIndex: 1, explanation: 'About 50% of incident solar radiation falls in the 400–700 nm range, defined as PAR.', difficulty: 'medium' },
  { id: 'eco-34', type: 'mcq', question: 'Of the available PAR, the percentage actually fixed by plants as chemical energy (NPP) is only about:', options: ['2–10%', '25–35%', '50–60%', '90–95%'], correctIndex: 0, explanation: 'Plants fix only 2–10% of the PAR available to them, reflecting the low overall efficiency of photosynthesis.', difficulty: 'medium' },
  { id: 'eco-35', type: 'mcq', question: 'Ecological succession is best defined as:', options: ['A sudden, one-time replacement of species', 'A gradual and predictable change in community structure over time in an area', 'The seasonal migration of animals', 'The daily activity pattern of an ecosystem'], correctIndex: 1, explanation: 'Succession is the gradual, directional change in species composition of a community over time.', difficulty: 'easy' },
  { id: 'eco-36', type: 'mcq', question: 'Succession that begins on a bare rock or newly cooled lava with no prior life is called:', options: ['Secondary succession', 'Primary succession', 'Cyclic succession', 'Autogenic succession only'], correctIndex: 1, explanation: 'Primary succession starts in a lifeless area with no pre-existing soil or organisms.', difficulty: 'easy' },
  { id: 'eco-37', type: 'mcq', question: 'Succession occurring in an area where an existing community was destroyed (e.g., an abandoned farmland or burned forest) is called:', options: ['Primary succession', 'Secondary succession', 'Hydrarch succession only', 'Xerarch succession only'], correctIndex: 1, explanation: 'Secondary succession occurs where soil and some life already exist, following a disturbance.', difficulty: 'easy' },
  { id: 'eco-38', type: 'mcq', question: 'The pioneer species in primary succession on bare rock (xerarch succession) are typically:', options: ['Trees', 'Lichens', 'Phytoplankton', 'Large mammals'], correctIndex: 1, explanation: 'Lichens are classic pioneers on bare rock, breaking it down and beginning soil formation.', difficulty: 'medium' },
  { id: 'eco-39', type: 'mcq', question: 'Succession that begins in a water body (like a pond) is called:', options: ['Xerarch succession', 'Hydrarch succession', 'Lithosere', 'Psammosere'], correctIndex: 1, explanation: 'Hydrarch succession proceeds from open water toward a terrestrial climax community.', difficulty: 'medium' },
  { id: 'eco-40', type: 'mcq', question: 'The entire sequence of communities that successively change in a given area is called a:', options: ['Sere', 'Biome', 'Ecotone', 'Niche'], correctIndex: 0, explanation: 'A "sere" is the complete series of communities that replace one another during succession.', difficulty: 'medium' },
  { id: 'eco-41', type: 'mcq', question: 'The final, relatively stable community at the end of succession is called the:', options: ['Pioneer community', 'Climax community', 'Transitional community', 'Detrital community'], correctIndex: 1, explanation: 'The climax community is the stable end-stage community that persists as long as the environment stays unchanged.', difficulty: 'easy' },
  { id: 'eco-42', type: 'mcq', question: 'The carbon cycle is classified as a:', options: ['Sedimentary cycle', 'Gaseous cycle', 'Non-recyclable cycle', 'Purely biological cycle with no atmospheric component'], correctIndex: 1, explanation: 'The carbon cycle has a large atmospheric (gaseous, CO2) reservoir, making it a gaseous-type biogeochemical cycle.', difficulty: 'easy' },
  { id: 'eco-43', type: 'mcq', question: 'The phosphorus cycle is classified as a:', options: ['Gaseous cycle', 'Sedimentary cycle', 'Cycle with no reservoir pool', 'Purely atmospheric cycle'], correctIndex: 1, explanation: "Phosphorus's main reservoir is rocks/sediments, making its cycle sedimentary rather than gaseous.", difficulty: 'easy' },
  { id: 'eco-44', type: 'mcq', question: "In nutrient cycling, the large storage site of a nutrient outside living organisms is called the:", options: ['Trophic level', 'Reservoir pool', 'Standing crop', 'Detrital pool only'], correctIndex: 1, explanation: 'The reservoir pool is the large, often abiotic, storage compartment of a nutrient in a biogeochemical cycle.', difficulty: 'medium' },
  { id: 'eco-45', type: 'mcq', question: 'Atmospheric carbon dioxide constitutes approximately what fraction of the total atmospheric pool relevant to the carbon cycle discussion?', options: ['About 0.03%', 'About 21%', 'About 78%', 'About 50%'], correctIndex: 0, explanation: 'CO2 makes up only about 0.03% of the atmosphere by volume, yet is central to the carbon cycle.', difficulty: 'medium' },
  { id: 'eco-46', type: 'mcq', question: 'Respiration by living organisms returns which gas to the atmospheric carbon pool?', options: ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Methane only'], correctIndex: 1, explanation: 'Respiration releases CO2 back to the atmosphere, completing part of the carbon cycle.', difficulty: 'easy' },
  { id: 'eco-47', type: 'mcq', question: 'Burning of fossil fuels contributes to the carbon cycle mainly by:', options: ['Removing CO2 from the atmosphere', 'Adding large amounts of CO2 to the atmosphere', 'Converting CO2 into limestone directly', 'Having no measurable effect on atmospheric carbon'], correctIndex: 1, explanation: 'Fossil fuel combustion releases carbon that had been locked away for millions of years, adding to atmospheric CO2.', difficulty: 'easy' },
  { id: 'eco-48', type: 'mcq', question: "Phosphorus's main natural reservoir is:", options: ['The atmosphere', 'Rocks and sediments', 'The ocean surface only', 'Living plant tissue'], correctIndex: 1, explanation: 'Unlike carbon or nitrogen, phosphorus has no significant atmospheric form — its reservoir is rock/sediment.', difficulty: 'medium' },
  { id: 'eco-49', type: 'mcq', question: 'Guano deposits and rock phosphate mining are both natural/human sources feeding into the:', options: ['Carbon cycle', 'Nitrogen cycle', 'Phosphorus cycle', 'Water cycle'], correctIndex: 2, explanation: 'Guano (bird droppings) and phosphate rock are both phosphorus-rich sources entering the phosphorus cycle.', difficulty: 'medium' },
  { id: 'eco-50', type: 'mcq', question: 'Which of the following is an example of an ecosystem service provided by natural ecosystems?', options: ['Pollination of crops by insects', 'Manufacturing of synthetic fertilisers', 'Construction of dams', 'Mining of minerals'], correctIndex: 0, explanation: 'Pollination is a classic ecosystem service — a benefit humans receive from natural ecological processes.', difficulty: 'easy' },

  // ---- Assertion-Reason ----
  { id: 'eco-ar-1', type: 'assertion-reason', question: 'Assertion (A): The pyramid of energy is always upright.\nReason (R): Energy transfer between successive trophic levels is never 100% efficient.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Energy loss at each transfer step guarantees a progressively smaller energy pool at higher trophic levels — always upright.', difficulty: 'medium' },
  { id: 'eco-ar-2', type: 'assertion-reason', question: 'Assertion (A): The pyramid of biomass in a sea ecosystem is generally inverted.\nReason (R): Phytoplankton have a very high reproduction and turnover rate compared to their standing biomass.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Rapid phytoplankton turnover means their standing crop can be small while still sustaining a much larger fish biomass — producing the inverted pyramid.', difficulty: 'medium' },
  { id: 'eco-ar-3', type: 'assertion-reason', question: 'Assertion (A): Decomposition is entirely an anaerobic process.\nReason (R): Detritivores and decomposers secrete extracellular enzymes to digest organic matter.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Decomposition is largely an oxygen-requiring (aerobic) process, so A is false; R correctly describes the mechanism of extracellular digestion.', difficulty: 'medium' },
  { id: 'eco-ar-4', type: 'assertion-reason', question: 'Assertion (A): Warm and moist environments favour rapid decomposition.\nReason (R): Such conditions are optimal for microbial (bacterial and fungal) growth and enzyme activity.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Warm, moist conditions favour decomposer activity precisely because they support optimal microbial growth.', difficulty: 'medium' },
  { id: 'eco-ar-5', type: 'assertion-reason', question: 'Assertion (A): Energy captured by producers is available to all trophic levels equally.\nReason (R): About 10% of energy is transferred from one trophic level to the next.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Energy actually decreases sharply at each level (A is false), which is exactly what the 10% law (R, true) describes.', difficulty: 'medium' },
  { id: 'eco-ar-6', type: 'assertion-reason', question: 'Assertion (A): Gross Primary Productivity is always equal to Net Primary Productivity.\nReason (R): Plants lose a portion of fixed energy to their own respiration.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'NPP is GPP minus respiration, so they are not equal (A is false); R correctly explains why they differ.', difficulty: 'medium' },
  { id: 'eco-ar-7', type: 'assertion-reason', question: 'Assertion (A): Lichens are important pioneer organisms in primary succession on bare rock.\nReason (R): They can grow on bare rock surfaces and help initiate soil formation.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Lichens' ability to colonise bare rock and begin weathering it is exactly why they act as pioneers.", difficulty: 'medium' },
  { id: 'eco-ar-8', type: 'assertion-reason', question: 'Assertion (A): Secondary succession is generally slower than primary succession.\nReason (R): Secondary succession starts on land that already has soil and possibly seeds or organisms present.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Secondary succession is actually FASTER (not slower) than primary succession, precisely because soil and propagules are already present — so A is false, R is true.', difficulty: 'medium' },
  { id: 'eco-ar-9', type: 'assertion-reason', question: 'Assertion (A): The carbon cycle is described as a gaseous-type biogeochemical cycle.\nReason (R): The atmosphere serves as a major reservoir pool for carbon dioxide.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "The atmosphere's role as a large CO2 reservoir is exactly what classifies carbon's cycle as gaseous.", difficulty: 'medium' },
  { id: 'eco-ar-10', type: 'assertion-reason', question: 'Assertion (A): The phosphorus cycle is a gaseous-type cycle.\nReason (R): The phosphorus cycle lacks any significant atmospheric gaseous phase.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "The phosphorus cycle is actually sedimentary, not gaseous, so A is false. R is true and is exactly why it's classified as sedimentary instead.", difficulty: 'medium' },
  { id: 'eco-ar-11', type: 'assertion-reason', question: 'Assertion (A): Detritivores play a critical role in decomposition.\nReason (R): They fragment detritus into smaller particles, increasing the surface area for microbial action.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Fragmentation by detritivores speeds up subsequent microbial decomposition — R directly explains why they matter.', difficulty: 'medium' },
  { id: 'eco-ar-12', type: 'assertion-reason', question: 'Assertion (A): Humus is rapidly decomposed by soil microbes.\nReason (R): Humus is highly resistant to microbial action and decomposes very slowly.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Humus is actually resistant and slow to decompose (A is false); R correctly states this resistance.', difficulty: 'medium' },
  { id: 'eco-ar-13', type: 'assertion-reason', question: 'Assertion (A): Only about 2–10% of the photosynthetically active radiation (PAR) is fixed by plants as NPP.\nReason (R): Photosynthesis is an inherently inefficient process at converting light energy into stored chemical energy.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "The low efficiency of photosynthesis (R) directly accounts for why only a small fraction of PAR becomes NPP (A).", difficulty: 'medium' },
  { id: 'eco-ar-14', type: 'assertion-reason', question: 'Assertion (A): Nutrients, unlike energy, can be recycled repeatedly within an ecosystem.\nReason (R): Decomposers release inorganic nutrients back into the soil/environment through mineralisation.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Mineralisation returning nutrients to the reservoir is exactly what enables their repeated recycling, unlike one-way energy flow.", difficulty: 'medium' },
  { id: 'eco-ar-15', type: 'assertion-reason', question: 'Assertion (A): A climax community remains completely unchanging forever once reached.\nReason (R): A climax community is in near-equilibrium with the prevailing environment as long as that environment remains stable.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "A climax community can still change if the environment changes — so 'forever unchanging' (A) is false; R correctly conditions its stability on a stable environment.", difficulty: 'medium' },
  { id: 'eco-ar-16', type: 'assertion-reason', question: 'Assertion (A): Hydrarch succession proceeds from a shallow water body towards a terrestrial community.\nReason (R): Silt and organic matter accumulate over time, gradually filling the water body.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Sediment and organic accumulation gradually converting water to land is exactly what drives hydrarch succession toward a terrestrial climax.', difficulty: 'medium' },
  { id: 'eco-ar-17', type: 'assertion-reason', question: 'Assertion (A): Top carnivores generally exist in much smaller numbers than herbivores in an ecosystem.\nReason (R): Only a small fraction of energy is available at each successive trophic level.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Progressively less energy at higher trophic levels supports fewer individuals — directly explaining why top carnivores are rarer.', difficulty: 'medium' },
  { id: 'eco-ar-18', type: 'assertion-reason', question: 'Assertion (A): Standing crop refers only to the number of individuals at a trophic level.\nReason (R): Standing crop can be measured either as the number of individuals or as biomass.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Standing crop can be expressed as biomass too, not just numbers, so A is too restrictive/false; R correctly notes both measures are valid.', difficulty: 'medium' },
  { id: 'eco-ar-19', type: 'assertion-reason', question: 'Assertion (A): Fossil fuel combustion has no significant impact on the global carbon cycle.\nReason (R): Fossil fuels release carbon that had been sequestered for millions of years, adding to atmospheric CO2 levels.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Fossil fuel burning has a major impact on the carbon cycle (A is false); R correctly explains why this impact occurs.', difficulty: 'medium' },
  { id: 'eco-ar-20', type: 'assertion-reason', question: 'Assertion (A): Ecological succession always leads to an increase in species diversity and community complexity over time, up to the climax stage.\nReason (R): Successive communities are generally better adapted to the local environment than the ones they replace.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: 'Both statements are broadly true for successional trends, but R (competitive adaptation driving replacement) is a separate mechanism from the general trend of rising diversity/complexity described in A — not its direct explanation.', difficulty: 'hard' },

  // ---- Statement-based ----
  { id: 'eco-st-1', type: 'statement', question: 'Statement I: The grazing food chain and detritus food chain are connected to each other in nature.\nStatement II: Detritivores can also be eaten by other consumers, linking the two chains.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'The GFC and DFC are indeed interconnected, partly through organisms that feed on detritivores.', difficulty: 'medium' },
  { id: 'eco-st-2', type: 'statement', question: 'Statement I: The pyramid of numbers is always upright.\nStatement II: In a tree ecosystem, the pyramid of numbers is spindle-shaped.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'The pyramid of numbers is NOT always upright (it can be spindle-shaped or inverted); Statement II correctly describes the tree-ecosystem exception.', difficulty: 'medium' },
  { id: 'eco-st-3', type: 'statement', question: 'Statement I: Gross Primary Productivity is measured as the total rate of organic matter production.\nStatement II: A considerable amount of GPP is used up by plants in respiration.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements accurately describe GPP and its relationship to respiratory loss.', difficulty: 'medium' },
  { id: 'eco-st-4', type: 'statement', question: 'Statement I: Productivity of an ecosystem is related to its standing crop.\nStatement II: Productivity refers to the rate of biomass production, while standing crop is the amount present at a given time.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'The two are related concepts — productivity is the rate, standing crop is the accumulated quantity at one point.', difficulty: 'medium' },
  { id: 'eco-st-5', type: 'statement', question: 'Statement I: Decomposition occurs only in the absence of oxygen.\nStatement II: Decomposers release digestive enzymes into detritus and then absorb the digested products.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Decomposition is largely an aerobic (oxygen-requiring) process, so Statement I is incorrect; Statement II correctly describes extracellular digestion by decomposers.', difficulty: 'medium' },
  { id: 'eco-st-6', type: 'statement', question: 'Statement I: Warm and moist conditions favour decomposition.\nStatement II: Cold and anaerobic conditions favour rapid decomposition, forming peat.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — cold, anaerobic conditions SLOW decomposition, which is why peat (partially decomposed matter) accumulates.', difficulty: 'medium' },
  { id: 'eco-st-7', type: 'statement', question: 'Statement I: Energy flow in an ecosystem is unidirectional.\nStatement II: Nutrient flow in an ecosystem is also strictly unidirectional.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Energy flow is unidirectional (Statement I correct), but nutrients are cycled and reused repeatedly, not one-way (Statement II incorrect).', difficulty: 'medium' },
  { id: 'eco-st-8', type: 'statement', question: "Statement I: According to the ten per cent law, 90% of energy is lost as heat at each trophic transfer.\nStatement II: This explains why food chains are usually limited to 3-4 trophic levels.", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements are correct and causally linked — severe energy loss limits how many trophic levels a chain can support.', difficulty: 'medium' },
  { id: 'eco-st-9', type: 'statement', question: 'Statement I: Primary succession begins on substrates that never previously supported life.\nStatement II: Secondary succession begins in areas that still possess some soil and organisms.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly distinguish primary from secondary succession by starting conditions.', difficulty: 'easy' },
  { id: 'eco-st-10', type: 'statement', question: 'Statement I: Lichens are the pioneer community in hydrarch succession.\nStatement II: Phytoplankton are typically the pioneers in hydrarch succession.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Lichens are pioneers of xerarch (bare rock) succession, not hydrarch; phytoplankton correctly represent hydrarch pioneers.', difficulty: 'medium' },
  { id: 'eco-st-11', type: 'statement', question: 'Statement I: A sere refers to a single stable community.\nStatement II: A sere refers to the entire sequence of communities that occur during succession.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect; Statement II correctly defines "sere" as the whole successional sequence.', difficulty: 'medium' },
  { id: 'eco-st-12', type: 'statement', question: 'Statement I: The carbon cycle is a sedimentary-type biogeochemical cycle.\nStatement II: The nitrogen cycle is generally regarded as a gaseous-type cycle.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'The carbon cycle is gaseous-type (atmospheric CO2 reservoir), so Statement I is incorrect; the nitrogen cycle, with its large atmospheric N2 reservoir, is correctly gaseous-type.', difficulty: 'medium' },
  { id: 'eco-st-13', type: 'statement', question: 'Statement I: Phosphorus does not have any significant gaseous phase.\nStatement II: The main reservoir of phosphorus is rocks and sediments.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe why the phosphorus cycle is sedimentary rather than gaseous.', difficulty: 'medium' },
  { id: 'eco-st-14', type: 'statement', question: 'Statement I: Only about 50% of incident solar radiation is Photosynthetically Active Radiation (PAR).\nStatement II: Plants are able to capture and fix nearly all of this PAR as chemical energy.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — plants fix only 2–10% of the available PAR, not nearly all of it.', difficulty: 'medium' },
  { id: 'eco-st-15', type: 'statement', question: 'Statement I: Ecosystem services include benefits like pollination and water purification provided free by nature.\nStatement II: These services have no economic value and cannot be estimated.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I correctly describes ecosystem services; Statement II is incorrect, as ecologists do estimate substantial economic value for these services.', difficulty: 'medium' },
  { id: 'eco-st-16', type: 'statement', question: 'Statement I: A food web has no ecological significance beyond looking more complex than a food chain.\nStatement II: A food web provides multiple energy pathways, adding resilience/stability to an ecosystem.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect; food webs meaningfully add ecological stability, as correctly described in Statement II.', difficulty: 'medium' },
  { id: 'eco-st-17', type: 'statement', question: 'Statement I: Standing crop can be expressed in terms of biomass per unit area.\nStatement II: Standing crop can also be expressed in terms of number of individuals per unit area.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Standing crop is flexible in units — both biomass and number of individuals are valid ways to express it.', difficulty: 'easy' },
  { id: 'eco-st-18', type: 'statement', question: 'Statement I: Mineralisation is carried out exclusively by fungi.\nStatement II: Both bacteria and fungi participate in the mineralisation step of decomposition.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — mineralisation is not exclusive to fungi; Statement II correctly notes both bacteria and fungi are involved.', difficulty: 'medium' },
  { id: 'eco-st-19', type: 'statement', question: 'Statement I: Climate strongly influences the rate of decomposition.\nStatement II: The chemical quality of detritus (e.g., lignin/chitin content) has no bearing on decomposition rate.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — detritus chemistry (like lignin or chitin content) strongly affects how quickly it decomposes.', difficulty: 'medium' },
  { id: 'eco-st-20', type: 'statement', question: 'Statement I: A climax community is completely static and shows zero species turnover.\nStatement II: A climax community remains in near-equilibrium with the environment as long as that environment does not change drastically.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I overstates the case (some turnover can still occur); Statement II is the more accurate description of climax community stability.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'eco-hm-1', type: 'statement', question: 'How many of the following are steps of decomposition, in the order they occur?\nFragmentation, Leaching, Catabolism, Humification and mineralisation', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'Fragmentation, leaching, catabolism, and humification/mineralisation are all recognised steps of decomposition.', difficulty: 'medium' },
  { id: 'eco-hm-2', type: 'statement', question: 'How many of the following are components of an ecosystem?\nProducers, Consumers, Decomposers, Abiotic components', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four — producers, consumers, decomposers, and abiotic factors — together make up an ecosystem.', difficulty: 'easy' },
  { id: 'eco-hm-3', type: 'statement', question: 'How many of the following ecological pyramids can be inverted, depending on the ecosystem?\nPyramid of numbers, Pyramid of biomass, Pyramid of energy', options: ['None', 'One', 'Two', 'All three'], correctIndex: 2, explanation: 'Pyramids of numbers and biomass can both be inverted in certain ecosystems; the pyramid of energy is always upright.', difficulty: 'medium' },
  { id: 'eco-hm-4', type: 'statement', question: 'How many of the following are types of ecological succession?\nPrimary succession, Secondary succession, Xerarch succession, Hydrarch succession', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are recognised categories/classifications of ecological succession.', difficulty: 'medium' },
  { id: 'eco-hm-5', type: 'statement', question: 'How many of the following are examples of gaseous-type biogeochemical cycles?\nCarbon cycle, Nitrogen cycle, Phosphorus cycle, Sulphur cycle', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Carbon and nitrogen cycles are gaseous-type (large atmospheric reservoirs); phosphorus is sedimentary, and sulphur is often considered intermediate/sedimentary in basic classification.', difficulty: 'hard' },
  { id: 'eco-hm-6', type: 'statement', question: 'How many of the following correctly describe Net Primary Productivity (NPP)?\nIt equals GPP minus respiration, It is available for consumption by heterotrophs, It is always greater than GPP, It represents new biomass added by plants', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: "GPP minus respiration, availability to heterotrophs, and representing new biomass are all correct; NPP is always LESS than (not greater than) GPP.", difficulty: 'medium' },
  { id: 'eco-hm-7', type: 'statement', question: 'How many of the following are examples of ecosystem services?\nPollination, Water purification by wetlands, Carbon sequestration by forests, Manufacturing of pesticides', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Pollination, water purification, and carbon sequestration are natural ecosystem services; pesticide manufacturing is a human industrial activity, not a service nature provides.', difficulty: 'medium' },
  { id: 'eco-hm-8', type: 'statement', question: 'How many of the following are true regarding the ten per cent law?\nIt was proposed by Lindeman, About 10% of energy passes to the next trophic level, It applies equally to all nutrient cycles, Energy loss occurs mainly as respiratory heat', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: "Lindeman's proposal, the ~10% transfer figure, and heat loss are all correct; the law is about energy, not nutrient cycles, so that statement is incorrect.", difficulty: 'medium' },
  { id: 'eco-hm-9', type: 'statement', question: 'How many of the following are stages typically seen during hydrarch succession, moving from open water toward land?\nPhytoplankton stage, Submerged plant stage, Reed-swamp stage, Woodland/forest stage', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four stages are part of the classic hydrarch succession sequence from open water to a terrestrial climax.', difficulty: 'hard' },
  { id: 'eco-hm-10', type: 'statement', question: 'How many of the following influence the rate of decomposition of detritus?\nTemperature, Moisture/soil aerobicity, Chemical composition of the detritus, Presence of detritivores and decomposers', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four factors — climate (temperature/moisture), detritus chemistry, and the presence of decomposer organisms — influence decomposition rate.', difficulty: 'medium' },
];
